 "content": "def transform(grid):
    """Extend same-color diagonal runs through background to the grid edge."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    if not h or not w:
        return [row[:] for row in grid]

    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # Each adjacent equal-color diagonal pair establishes a diagonal line.
    # Extend outward from either end while cells are still background.
    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                nr, nc = r + dr, c + dc
                if nr >= h or not 0 <= nc < w or grid[r][c] == background or grid[nr][nc] != grid[r][c]:
                    continue
                color = grid[r][c]
                for sr, sc, step_r, step_c in ((r, c, -dr, -dc), (nr, nc, dr, dc)):
                    rr, cc = sr + step_r, sc + step_c
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == background:
                        out[rr][cc] = color
                        rr += step_r
                        cc += step_c
    return out

if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))

